v_rcp_f64 v[2:3], v[2:3]                           // s14 = s[sgprNumWorkGroups0] / s12
v_cvt_f64_u32 v[4:5], s[sgprNumWorkGroups0]        // s14 = s[sgprNumWorkGroups0] / s12
v_mul_f64 v[2:3], v[2:3], v[4:5]                   // s14 = s[sgprNumWorkGroups0] / s12
v_cvt_u32_f64 v2, v[2:3]                           // s14 = s[sgprNumWorkGroups0] / s12
v_mul_lo_u32 v3, v2, s12                           // s14 = s[sgprNumWorkGroups0] / s12
v_sub_u32 v4, s[sgprNumWorkGroups0], v3            // s14 = s[sgprNumWorkGroups0] / s12
v_cmpx_ge_u32 exec, v4, s12                        // s14 = s[sgprNumWorkGroups0] / s12
v_add_u32 v2, v2, 1                                // s14 = s[sgprNumWorkGroups0] / s12
s_mov_b64 exec, -1                                 // Reset exec
v_readfirstlane_b32 s14, v2                        // quotient
s_mul_i32 s15, s12, s14                            // quotient * non-magic divisor
s_sub_u32 s15, s[sgprNumWorkGroups0], s15          // NumWorkGroups0=remainder
s_cmp_eq_u32 s15, 0                                // remainder == 0 ?
s_cmov_b32 s15, s12                                // remainder = WGM if remainder == 0
s_cmp_ge_u32 s13, s14                              // blockId >= numFullBlocks ?
s_cselect_b32 s14, s15, s12
v_cvt_f64_u32 v[2:3], s14                          // s[sgprWorkGroup1] = s56 / s14
v_rcp_f64 v[2:3], v[2:3]                           // s[sgprWorkGroup1] = s56 / s14
v_cvt_f64_u32 v[4:5], s56                          // s[sgprWorkGroup1] = s56 / s14
v_mul_f64 v[2:3], v[2:3], v[4:5]                   // s[sgprWorkGroup1] = s56 / s14
v_cvt_u32_f64 v2, v[2:3]                           // s[sgprWorkGroup1] = s56 / s14
v_mul_lo_u32 v3, v2, s14                           // s[sgprWorkGroup1] = s56 / s14
v_sub_u32 v4, s56, v3                              // s[sgprWorkGroup1] = s56 / s14
v_cmpx_ge_u32 exec, v4, s14                        // s[sgprWorkGroup1] = s56 / s14
v_add_u32 v2, v2, 1                                // s[sgprWorkGroup1] = s56 / s14
s_mov_b64 exec, -1                                 // Reset exec
v_mul_lo_u32 v3, v2, s14                           // s[sgprWorkGroup1] = s56 / s14
v_sub_u32 v4, s56, v3                              // s[sgprWorkGroup1] = s56 / s14
v_readfirstlane_b32 s[sgprWorkGroup1], v2          // quotient
v_readfirstlane_b32 s[sgprWorkGroup0], v4          // remainder
s_mul_i32 s[sgprWorkGroup0], s[sgprWorkGroup1], s14 // quotient * non-magic divisor
s_sub_u32 s[sgprWorkGroup0], s56, s[sgprWorkGroup0] // WorkGroup0=remainder
s_mul_i32 s13, s13, s12                            // blockId * WGM
s_add_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s13 // wg1 += blockId * WGM
s_branch label_WGM
label_WGMPositive:
s_mov_b32 s12, s12                                 // WGM
v_cvt_f64_u32 v[2:3], s12                          // s13 = s[sgprWorkGroup1] / s12
v_rcp_f64 v[2:3], v[2:3]                           // s13 = s[sgprWorkGroup1] / s12
v_cvt_f64_u32 v[4:5], s[sgprWorkGroup1]            // s13 = s[sgprWorkGroup1] / s12
v_mul_f64 v[2:3], v[2:3], v[4:5]                   // s13 = s[sgprWorkGroup1] / s12
v_cvt_u32_f64 v2, v[2:3]                           // s13 = s[sgprWorkGroup1] / s12
v_mul_lo_u32 v3, v2, s12                           // s13 = s[sgprWorkGroup1] / s12
v_sub_u32 v4, s[sgprWorkGroup1], v3                // s13 = s[sgprWorkGroup1] / s12
v_cmpx_ge_u32 exec, v4, s12                        // s13 = s[sgprWorkGroup1] / s12
v_add_u32 v2, v2, 1                                // s13 = s[sgprWorkGroup1] / s12
s_mov_b64 exec, -1                                 // Reset exec
v_readfirstlane_b32 s13, v2                        // quotient
s_mul_i32 s56, s13, s12                            // quotient * non-magic divisor
s_sub_u32 s56, s[sgprWorkGroup1], s56              // WorkGroup1=remainder
s_mul_i32 s56, s56, s[sgprNumWorkGroups0]          // (wg1 % WGM)*NumWorkGroups0
s_add_u32 s56, s56, s[sgprWorkGroup0]              // wgSerial = wg0 + (wg1 % WGM)*NumWorkGroups0
v_cvt_f64_u32 v[2:3], s12                          // s14 = s[sgprNumWorkGroups1] / s12
v_rcp_f64 v[2:3], v[2:3]                           // s14 = s[sgprNumWorkGroups1] / s12
v_cvt_f64_u32 v[4:5], s[sgprNumWorkGroups1]        // s14 = s[sgprNumWorkGroups1] / s12
v_mul_f64 v[2:3], v[2:3], v[4:5]                   // s14 = s[sgprNumWorkGroups1] / s12
v_cvt_u32_f64 v2, v[2:3]                           // s14 = s[sgprNumWorkGroups1] / s12
v_mul_lo_u32 v3, v2, s12                           // s14 = s[sgprNumWorkGroups1] / s12
v_sub_u32 v4, s[sgprNumWorkGroups1], v3            // s14 = s[sgprNumWorkGroups1] / s12
v_cmpx_ge_u32 exec, v4, s12                        // s14 = s[sgprNumWorkGroups1] / s12
v_add_u32 v2, v2, 1                                // s14 = s[sgprNumWorkGroups1] / s12
s_mov_b64 exec, -1                                 // Reset exec
v_readfirstlane_b32 s14, v2                        // quotient
s_mul_i32 s15, s12, s14                            // quotient * non-magic divisor
s_sub_u32 s15, s[sgprNumWorkGroups1], s15          // NumWorkGroups1=remainder
s_cmp_eq_u32 s15, 0                                // remainder == 0 ?
s_cmov_b32 s15, s12                                // remainder = WGM if remainder == 0
s_cmp_ge_u32 s13, s14                              // blockId >= numFullBlocks ?
s_cselect_b32 s14, s15, s12
v_cvt_f64_u32 v[2:3], s14                          // s[sgprWorkGroup0] = s56 / s14
v_rcp_f64 v[2:3], v[2:3]                           // s[sgprWorkGroup0] = s56 / s14
v_cvt_f64_u32 v[4:5], s56                          // s[sgprWorkGroup0] = s56 / s14
v_mul_f64 v[2:3], v[2:3], v[4:5]                   // s[sgprWorkGroup0] = s56 / s14
v_cvt_u32_f64 v2, v[2:3]                           // s[sgprWorkGroup0] = s56 / s14
v_mul_lo_u32 v3, v2, s14                           // s[sgprWorkGroup0] = s56 / s14
v_sub_u32 v4, s56, v3                              // s[sgprWorkGroup0] = s56 / s14
v_cmpx_ge_u32 exec, v4, s14                        // s[sgprWorkGroup0] = s56 / s14
v_add_u32 v2, v2, 1                                // s[sgprWorkGroup0] = s56 / s14
s_mov_b64 exec, -1                                 // Reset exec
v_mul_lo_u32 v3, v2, s14                           // s[sgprWorkGroup0] = s56 / s14
v_sub_u32 v4, s56, v3                              // s[sgprWorkGroup0] = s56 / s14
v_readfirstlane_b32 s[sgprWorkGroup0], v2          // quotient
v_readfirstlane_b32 s[sgprWorkGroup1], v4          // remainder
s_mul_i32 s[sgprWorkGroup1], s[sgprWorkGroup0], s14 // quotient * non-magic divisor
s_sub_u32 s[sgprWorkGroup1], s56, s[sgprWorkGroup1] // WorkGroup1=remainder
s_mul_i32 s13, s13, s12                            // blockId * WGM
s_add_u32 s[sgprWorkGroup1], s[sgprWorkGroup1], s13 // wg1 += blockId * WGM
label_WGM:

/******************************************/
/* End setupNewTile                       */
/******************************************/
/* Compute shared offsets used by m0 in DTL loads */
v_lshrrev_b32 v1, 0x6, v[vgprSerial]               // Wave Id
s_mov_b32 s56, 128                                 // A: row offset
v_and_b32 v4, 0x1, v1                              // A: waveId % 2
v_lshrrev_b32 v5, 0x1, v1                          // A: waveId / 2
v_lshlrev_b32 v4, 0x3, v4                          // A: local row offset
v_mul_lo_u32 v5, s56, v5                           // A: wave row offset
v_add_u32 v2, v4, v5                               // A: row offset
s_mov_b32 s56, 128                                 // B: row offset
v_and_b32 v4, 0x1, v1                              // B: waveId % 2
v_lshrrev_b32 v5, 0x1, v1                          // B: waveId / 2
v_lshlrev_b32 v4, 0x3, v4                          // B: local row offset
v_mul_lo_u32 v5, s56, v5                           // B: wave row offset
v_add_u32 v3, v4, v5                               // B: row offset
v_lshlrev_b32 v2, 0x7, v2                          // Apply wave-specific offset for A
v_lshlrev_b32 v3, 0x7, v3                          // Apply wave-specific offset for B
s_nop 0                                            // Wait for VGPR to be ready
v_readfirstlane_b32 s[sgprLocalWriteBaseAddrA], v2 // Store base LDS offset, will be modified
v_readfirstlane_b32 s[sgprLocalWriteBaseAddrB], v3 // Store base LDS offset, will be modified
s_lshr_b32 s56, s[sgprLocalWriteBaseAddrA], 0xa    // block index = base / 1024
s_mul_i32 s56, s56, 0x20                           // padding 32 per block 1024
s_add_u32 s[sgprLocalWriteBaseAddrA], s[sgprLocalWriteBaseAddrA], s56 // apply LDS block padding to wave base
s_lshr_b32 s56, s[sgprLocalWriteBaseAddrB], 0xa    // block index = base / 1024
s_mul_i32 s56, s56, 0x20                           // padding 32 per block 1024
s_add_u32 s[sgprLocalWriteBaseAddrB], s[sgprLocalWriteBaseAddrB], s56 // apply LDS block padding to wave base
s_add_u32 s[sgprLocalWriteBaseAddrB], s[sgprLocalWriteBaseAddrB], 0x9000
s_add_u32 s[sgprSwapA], s[sgprLocalWriteBaseAddrA], 81920
s_xor_b32 s[sgprSwapA], s[sgprLocalWriteBaseAddrA], s[sgprSwapA]
s_add_u32 s[sgprSwapB], s[sgprLocalWriteBaseAddrB], 81920
s_xor_b32 s[sgprSwapB], s[sgprLocalWriteBaseAddrB], s[sgprSwapB]
/* Compute shared offsets used by m0 in DTL loads */
v_lshrrev_b32 v1, 0x6, v[vgprSerial]               // Wave Id
v_lshlrev_b32 v1, 0xa, v1                          // Apply wave-specific common offset (1024) for A/B
s_nop 0                                            // Wait for VGPR to be ready
v_readfirstlane_b32 s[sgprLocalWriteBaseAddrMXSA], v1 // Store base LDS offset, will be modified
v_readfirstlane_b32 s[sgprLocalWriteBaseAddrMXSB], v1 // Store base LDS offset, will be modified
s_add_u32 s[sgprLocalWriteBaseAddrMXSA], s[sgprLocalWriteBaseAddrMXSA], 0x12000
s_add_u32 s[sgprLocalWriteBaseAddrMXSB], s[sgprLocalWriteBaseAddrMXSB], 0x13000
s_add_u32 s[sgprSwapMXSA], s[sgprLocalWriteBaseAddrMXSA], 81920
s_xor_b32 s[sgprSwapMXSA], s[sgprLocalWriteBaseAddrMXSA], s[sgprSwapMXSA]
s_add_u32 s[sgprSwapMXSB], s[sgprLocalWriteBaseAddrMXSB], 81920
s_xor_b32 s[sgprSwapMXSB], s[sgprLocalWriteBaseAddrMXSB], s[sgprSwapMXSB]

/* global read addresses: addresses a */
/* max read offset = size[n] * stride[n-1] */
s_mul_hi_u32 s91, s[sgprWorkGroup0], 256           // WorkGroup[01] * roundup(MT/1)
s_mul_i32 s90, s[sgprWorkGroup0], 256              // WorkGroup[01] * roundup(MT/1)
s_sub_u32 s88, s[sgprSizeI], s90                   // numToEnd = size - WG*MT
s_min_u32 s88, s88, 256                            // min (numBlkToEnd, roundup(MT/1))
s_sub_u32 s88, s88, 1                              // numLine = min - 1 (0-based index)
s_mul_hi_u32 s89, s88, s[sgprStrideA0I]            // numLine * stride
s_mul_i32 s88, s88, s[sgprStrideA0I]               // numLine * stride
s_add_u32 s88, s88, 256                            // + DepthU (one K step)
s_lshr_b32 s[sgprSrdA+2], s88, 1                   // buffer_load limit for A (tile-boundary, avoids 32-bit overflow) (multiple bpe)
s_mul_hi_u32 s91, s90, s[sgprStrideA0I]            // tlu=0, scaled tile-offset by stride
s_mul_i32 s90, s90, s[sgprStrideA0I]               // tlu=0, scaled tile-offset by stride
s_mul_i32 s88, s[sgprStreamKLocalStart], 256       // StreamK tile start offset
s_mul_hi_u32 s89, s88, constStrideAL               // StreamK tile start offset
s_mul_i32 s88, s88, constStrideAL                  // StreamK tile start offset
s_add_u32 s90, s90, s88                            // accum GsuOffset term to tilestart
s_addc_u32 s91, s91, s89                           // accum GsuOffset term to tilestart
s_cmp_eq_u32 s[sgprArgType], 3                     // ArgType == 3 for General Batched GEMM
s_cbranch_scc0 label_StridedBatchedGemmLoadA
s_mul_i32 s88, 8, s[sgprWorkGroup2]                // Compute Offset into Pointer Array
s_cmp_eq_u32 s[sgprSizesSum], 0x0                  // Don't dereference Pointer array if SizesSum == 0
s_cbranch_scc1 label_StridedBatchedGemmLoadA_End
s_add_u32 s88, s88, s[sgprAddressA+0]              // Offsetting to the location [Lower half of address]
s_addc_u32 s89, s[sgprAddressA+1], 0               // Offsetting to the location [Higher half of address]
s_load_dwordx2 s[sgprSrdA:sgprSrdA+1], s[88:89], 0 // Load the Matrix Address in the Pointer Array
s_load_dwordx2 s[88:89], s[sgprKernArgAddress:sgprKernArgAddress+1], 0xe4 // Load batchOffsetA from kernel args
s_waitcnt lgkmcnt(0)                               // Wait for Matrix Address and Batch Offset Loads
s_add_u32 s[sgprSrdA+0], s[sgprSrdA+0], s88        // Add batch offset to A address (low)
s_addc_u32 s[sgprSrdA+1], s[sgprSrdA+1], s89       // Add batch offset to A address (high)
s_sub_u32 s[sgprSrdA+0], s[sgprSrdA+0], 0          // pre-pad to make room for possible pointer shift
s_subb_u32 s[sgprSrdA+1], s[sgprSrdA+1], 0         // pre-pad to make room for possible pointer shift
s_lshr_b64 s[90:91], s[90:91], 1                   // tileStart (multiple bpe)
s_add_u32 s[sgprSrdA+0], s90, s[sgprSrdA+0]        // SRD base = Address+ tileStart0
s_addc_u32 s[sgprSrdA+1], s91, s[sgprSrdA+1]       // SRD base = Address+ tileStart1
s_branch label_StridedBatchedGemmLoadA_End
label_StridedBatchedGemmLoadA:  /// Computing the Batch Matrix's base address for Strided Batched GEMM
s_mul_hi_u32 s89, s[sgprStrideAK], s[sgprWorkGroup2] // Stride*WG
s_mul_i32 s88, s[sgprStrideAK], s[sgprWorkGroup2]  // Stride*WG
s_add_u32 s90, s90, s88                            // accum wg term to tilestart
s_addc_u32 s91, s91, s89                           // accum wg term to tilestart
s_lshr_b64 s[90:91], s[90:91], 1                   // tileStart (multiple bpe)
s_add_u32 s[sgprSrdA+0], s[sgprAddressA+0], s90    // SRD base = Address+ tileStart0
s_addc_u32 s[sgprSrdA+1], s[sgprAddressA+1], s91   // SRD base = Address+ tileStart1
label_StridedBatchedGemmLoadA_End:  /// End Computing the Batch Matrix's base address for Strided Batched
s_mov_b32 s[sgprSrdA+3], Srd127_96                 // Set bits 127_96 in SRD

/* global read addresses: addresses mxsa */
/* max read offset = size[n] * stride[n-1] */
s_mul_hi_u32 s91, s[sgprWorkGroup0], 8             // WorkGroup[01] * roundup(MT/32)
s_mul_i32 s90, s[sgprWorkGroup0], 8                // WorkGroup[01] * roundup(MT/32)
s_add_u32 s88, s[sgprSizeI], 31                    // size + 32 - 1
s_lshr_b32 s88, s88, 5                             // roundup(size/32)
s_sub_u32 s88, s88, s90                            // numBlkToEnd = roundUp(size/32) - tileStart_blk
s_min_u32 s88, s88, 8                              // min (numBlkToEnd, roundup(MT/32))
s_sub_u32 s88, s88, 1                              // numLine = min - 1 (0-based index)
s_mul_hi_u32 s89, s88, s[sgprStrideMXSA0I]         // numLine * stride
s_mul_i32 s88, s88, s[sgprStrideMXSA0I]            // numLine * stride
s_add_u32 s[sgprSrdMXSA+2], s88, 256               // buffer_load limit for MXSA
s_mul_hi_u32 s91, s90, s[sgprStrideMXSA0I]         // tlu=0, scaled tile-offset by stride
s_mul_i32 s90, s90, s[sgprStrideMXSA0I]            // tlu=0, scaled tile-offset by stride
s_mul_i32 s88, s[sgprStreamKLocalStart], 256       // StreamK tile start offset
s_mul_hi_u32 s89, s88, constStrideMXSAL            // StreamK tile start offset
s_mul_i32 s88, s88, constStrideMXSAL               // StreamK tile start offset
s_add_u32 s90, s90, s88                            // accum GsuOffset term to tilestart
s_addc_u32 s91, s91, s89                           // accum GsuOffset term to tilestart
s_cmp_eq_u32 s[sgprArgType], 3                     // ArgType == 3 for General Batched GEMM
s_cbranch_scc0 label_StridedBatchedGemmLoadMXSA
s_mul_i32 s88, 8, s[sgprWorkGroup2]                // Compute Offset into Pointer Array
s_cmp_eq_u32 s[sgprSizesSum], 0x0                  // Don't dereference Pointer array if SizesSum == 0
s_cbranch_scc1 label_StridedBatchedGemmLoadMXSA_End
s_add_u32 s88, s88, s[sgprAddressMXSA+0]           // Offsetting to the location [Lower half of address]
s_addc_u32 s89, s[sgprAddressMXSA+1], 0            // Offsetting to the location [Higher half of address]
s_load_dwordx2 s[sgprSrdMXSA:sgprSrdMXSA+1], s[88:89], 0 // Load the Matrix Address in the Pointer Array
s_load_dwordx2 s[88:89], s[sgprKernArgAddress:sgprKernArgAddress+1], 0xec // Load batchOffsetMXSA from kernel args
s_waitcnt lgkmcnt(0)                               // Wait for Matrix Address and Batch Offset Loads
s_add_u32 s[sgprSrdMXSA+0], s[sgprSrdMXSA+0], s88  // Add batch offset to MXSA address (low)
s_addc_u32 s[sgprSrdMXSA+1], s[sgprSrdMXSA+1], s89 // Add batch offset to MXSA address (high)
                                                   // tileStart (bpe is 1, do nothing)
s_add_u32 s[sgprSrdMXSA+0], s90, s[sgprSrdMXSA+0]  // SRD base = Address+ tileStart0
s_addc_u32 s[sgprSrdMXSA+1], s91, s[sgprSrdMXSA+1] // SRD base = Address+ tileStart1
s_branch label_StridedBatchedGemmLoadMXSA_End
label_StridedBatchedGemmLoadMXSA:  /// Computing the Batch Matrix's base address for Strided Batched GEMM
s_mul_hi_u32 s89, s[sgprStrideMXSAK], s[sgprWorkGroup2] // Stride*WG
s_mul_i32 s88, s[sgprStrideMXSAK], s[sgprWorkGroup2] // Stride*WG
s_add_u32 s90, s90, s88                            // accum wg term to tilestart
s_addc_u32 s91, s91, s89                           // accum wg term to tilestart
                                                   // tileStart (bpe is 1, do nothing)
s_add_u32 s[sgprSrdMXSA+0], s[sgprAddressMXSA+0], s90 // SRD base = Address+ tileStart0
s_addc_u32 s[sgprSrdMXSA+1], s[sgprAddressMXSA+1], s91 // SRD base = Address+ tileStart1
label_StridedBatchedGemmLoadMXSA_End:  /// End Computing the Batch Matrix's base address for Strided Batched
s_mov_b32 s[sgprSrdMXSA+3], Srd127_96              // Set bits 127_96 in SRD

/* global read addresses: addresses b */
/* max read offset = size[n] * stride[n-1] */
s_mul_hi_u32 s91, s[sgprWorkGroup1], 256           // WorkGroup[01] * roundup(MT/1)
s_mul_i32 s90, s[sgprWorkGroup1], 256              // WorkGroup[01] * roundup(MT/1)
s_sub_u32 s88, s[sgprSizeJ], s90                   // numToEnd = size - WG*MT
s_min_u32 s88, s88, 256                            // min (numBlkToEnd, roundup(MT/1))
s_sub_u32 s88, s88, 1                              // numLine = min - 1 (0-based index)
s_mul_hi_u32 s89, s88, s[sgprStrideB1J]            // numLine * stride
s_mul_i32 s88, s88, s[sgprStrideB1J]               // numLine * stride
s_add_u32 s88, s88, 256                            // + DepthU (one K step)
s_lshr_b32 s[sgprSrdB+2], s88, 1                   // buffer_load limit for B (tile-boundary, avoids 32-bit overflow) (multiple bpe)
s_mul_hi_u32 s91, s90, s[sgprStrideB1J]            // tlu=0, scaled tile-offset by stride
s_mul_i32 s90, s90, s[sgprStrideB1J]               // tlu=0, scaled tile-offset by stride
s_mul_i32 s88, s[sgprStreamKLocalStart], 256       // StreamK tile start offset
s_mul_hi_u32 s89, s88, constStrideBL               // StreamK tile start offset
s_mul_i32 s88, s88, constStrideBL                  // StreamK tile start offset
s_add_u32 s90, s90, s88                            // accum GsuOffset term to tilestart
s_addc_u32 s91, s91, s89                           // accum GsuOffset term to tilestart
s_cmp_eq_u32 s[sgprArgType], 3                     // ArgType == 3 for General Batched GEMM
s_cbranch_scc0 label_StridedBatchedGemmLoadB
s_mul_i32 s88, 8, s[sgprWorkGroup2]                // Compute Offset into Pointer Array
s_cmp_eq_u32 s[sgprSizesSum], 0x0                  // Don't dereference Pointer array if SizesSum == 0
s_cbranch_scc1 label_StridedBatchedGemmLoadB_End
s_add_u32 s88, s88, s[sgprAddressB+0]              // Offsetting to the location [Lower half of address]
s_addc_u32 s89, s[sgprAddressB+1], 0               // Offsetting to the location [Higher half of address]
s_load_dwordx2 s[sgprSrdB:sgprSrdB+1], s[88:89], 0 // Load the Matrix Address in the Pointer Array
s_load_dwordx2 s[88:89], s[sgprKernArgAddress:sgprKernArgAddress+1], 0xec // Load batchOffsetB from kernel args
s_waitcnt lgkmcnt(0)                               // Wait for Matrix Address and Batch Offset Loads
s_add_u32 s[sgprSrdB+0], s[sgprSrdB+0], s88        // Add batch offset to B address (low)
s_addc_u32 s[sgprSrdB+1], s[sgprSrdB+1], s89       // Add batch offset to B address (high)
s_sub_u32 s[sgprSrdB+0], s[sgprSrdB+0], 0          // pre-pad to make room for possible pointer shift
s_subb_u32 s[sgprSrdB+1], s[sgprSrdB+1], 0         // pre-pad to make room for possible pointer shift
s_lshr_b64 s[90:91], s[90:91], 1                   // tileStart (multiple bpe)
s_add_u32 s[sgprSrdB+0], s90, s[sgprSrdB+0]        // SRD base = Address+ tileStart0
s_addc_u32 s[sgprSrdB+1], s91, s[sgprSrdB+1]       // SRD base = Address+ tileStart1
s_branch label_StridedBatchedGemmLoadB_End
label_StridedBatchedGemmLoadB:  /// Computing the Batch Matrix's base address for Strided Batched GEMM
