v_readfirstlane_b32 s[sgprAlpha], v6               // Update Alpha
s_cmp_eq_u32 s[sgprStreamKLocalStart], 0           // does wg start tile?
s_cbranch_scc1 label_NoBranch_ZU0B7F2XE71N7LVL     // Only branch on scc0
