s_setpc_b64 s[78:79]                               // branch to label_SK_Partials_1
label_NoBranch_ZU0B7F2XE71N7LVL:
s_cmp_eq_u32 s[sgprStreamKLocalEnd], s[sgprItersPerTile] // does wg finish tile?
