s_cmp_eq_u32 s75, 0                                // Check for wave 0
s_cbranch_scc0 label_SK_SkipFlagReset              // Skip flag reset
s_store_dword s75, s[sgprAddressFlags:sgprAddressFlags+1], s73 glc // reset flag
